    def break_all_links_between_devices(self,
                                        reservation_id,
                                        first_device_name,
                                        second_device_name,
                                        link_index=None):
        """
        Method to break all links between two resources connected
        by switch in active reservation. Method breaks links in
        series. Individual links can be break separately using
        link indexes. Resource names are case sensitive.

        :param reservation_id: ID of the reservation
        :type reservation_d: str
        :param first_device_name: first of linked devices: str
        :type first_device_name: str
        :param second_device_name: second lined devices: str
        :type second_device_name: str
        :param link_index: list of link indexes to break: list
        :type link_index: list

        :return: list {job_id, status}
        """
        resource_inv_ids = self._get_res_inventory_ids(reservation_id,
                                                       first_device_name,
                                                       second_device_name,)
        if resource_inv_ids == [] or resource_inv_ids is None:
            return {'job-id': '', 'status': "FAILED", 'reason': 'Could not ' \
                    'find all resources. Check names ' \
                    f'{first_device_name}, {second_device_name}'}

        link_ids = self._check_multiple_link_ids(reservation_id,
                                                 resource_inv_ids)
        if link_ids is None:
            self.logger.error("No link ids parsed. Check devices names.")
            return False
        try:
            if link_index is not None:
                if type(link_index) == int: link_index = [link_index]
                link_ids = [link_ids[i] for i in link_index]
        except IndexError as e:
            self.logger.error(f"Invalid link index input list. {e}")
            return False

        ret_list = []
        for link_id in link_ids:
            response = self._break_link(reservation_id, link_id)
            status = self._check_status_of_modification(
                response['jobId'], reservation_id
            )
            ret_list.append({'job-id': response['jobId'], 'status': status})

        return ret_list

