    def delete_connection_between_devices(
            self, reservation_id: str, first_device_name: str,
            first_port_name: str, sec_device_name: str,
            sec_port_name: str) -> dict:
        """
        Method for delete connection between devices.
        Support link types: Coax, Opt, RP3, Sync and Eth
        Raise Exception in case of error!

        :param reservation_id: ID of the reservation
        :type reservation_id: str
        :param first_device_name: Name of first devices
        :type first_device_name: str
        :param first_port_name: Port name from first devices
        :type first_port_name: str
        :param sec_device_name: Name of second devices
        :type sec_device_name: str
        :param sec_port_name: Port name from second devices
        :type sec_port_name: str

        returns: job_id, status
        rtype: dict[str, str]
        """

        rsv_yaml = yaml.safe_load(
            self.get_reservation_yaml(reservation_id=reservation_id)
        )

        res_resources = self.get_reservation_resources(reservation_id, limit=200)
        first_device_id, first_dev_inventory_name = self._get_inventory_id_and_name(res_resources,
                                                                                    first_device_name,
                                                                                    "DEVICE")
        sec_device_id, sec_dev_inventory_name = self._get_inventory_id_and_name(res_resources,
                                                                                sec_device_name,
                                                                                "DEVICE")

        first_port_id = self._get_device_port_id(
            first_device_id, first_port_name
        )
        sec_port_id = self._get_device_port_id(
            sec_device_id, sec_port_name
        )

        first_port_id_rsv = self._get_rsv_id(
            _type='Port',
            inventory_id=first_port_id,
            rsv_yaml=rsv_yaml
        )
        sec_port_id_rsv = self._get_rsv_id(
            _type='Port',
            inventory_id=sec_port_id,
            rsv_yaml=rsv_yaml
        )
        if not first_port_id_rsv or not sec_port_id_rsv:
            raise Exception("Please check port names and that connection is active! " \
                            f"First port rsv status: {True if first_port_id_rsv != False else False}, " \
                            f"Second port rsv status: {True if sec_port_id_rsv != False else False}.")

        del rsv_yaml['topology_template']['node_templates']["port_" + first_port_id_rsv]
        del rsv_yaml['topology_template']['node_templates']["port_" + sec_port_id_rsv]

        name_link_id = self._get_typed_link_id(rsv_yaml, first_port_id_rsv)
        if name_link_id is not None:
            del rsv_yaml['topology_template']['node_templates'][name_link_id]
        else:
            raise Exception(
                f"No connection between {first_device_name}.{first_port_name} and {sec_device_name}.{sec_port_name}"
            )

        response, status = self._update_reservation_using_yaml(rsv_yaml, reservation_id)
        return {'job-id': response['jobId'], 'status': status}

    def get_rf_route_cable_ids(self, reservation_id, from_device_name, to_device_name):
        """
            Get RF route cable ID information between two resources.
            Given resources can be any devices as long there is active RF cabel connection between them.
            From returned data, first routeId value is connected to the from_device_name and
            the last value from returned data is connected to to_device_name.
            If given device has no links and route data could not be fetched, return empty dict.
            Example return data: {'route_cables': ['RF07-6345', 'RF04-0912']}

            :param from_device_name: str
            :param to_device_name: str
            :param reservation_id: str
            :return: route_cables
            :rtype: dict[list]
        """

        route_cabels = []
        topology_links_and_route = self.get_reserved_topology_links(reservation_id,
                                                                    onlyPortLinks="true",
                                                                    withConnections="true")
        for link_data in topology_links_and_route['items']:
            if link_data['parentResource1']['name'] == to_device_name \
            and link_data['parentResource2']['name'] == from_device_name:
                reverse_cable_id_list = True
                link_with_resources = link_data
                break
            elif link_data['parentResource2']['name'] == to_device_name \
                    and link_data['parentResource1']['name'] == from_device_name:
                reverse_cable_id_list = False
                link_with_resources = link_data
                break
        else:
            # Retry logic: search reservation resources for alternate names
            res_resources = self.get_reservation_resources(reservation_id)

            def get_possible_names(device_name, res_resources):
                names = set()
                for item in res_resources['items']:
                    if item.get('name') == device_name or item.get('inventoryResourceName') == device_name:
                        names.add(item.get('name'))
                        names.add(item.get('inventoryResourceName'))
                return names

            res_resources = self.get_reservation_resources(reservation_id)
            from_names = get_possible_names(from_device_name, res_resources)
            to_names = get_possible_names(to_device_name, res_resources)

            found = False
            for link_data in topology_links_and_route['items']:
                pr1 = link_data['parentResource1']['name']
                pr2 = link_data['parentResource2']['name']
                if pr1 in to_names and pr2 in from_names:
                    reverse_cable_id_list = True
                    link_with_resources = link_data
                    found = True
                    break
                elif pr2 in to_names and pr1 in from_names:
                    reverse_cable_id_list = False
                    link_with_resources = link_data
                    found = True
                    break

            if not found:
                self.logger.error(f"reservation_id: '{reservation_id}'")
                self.logger.error(f"to_device_name: '{to_device_name}'")
                self.logger.error(f"from_device_name: '{from_device_name}'")
                self.logger.error(f"topology_links_and_route: '{topology_links_and_route}'")
                raise Exception(
                    f"Link between resources '{from_device_name} <-> {to_device_name}' could not be found! "
                    "Check names and topology!"
                )

        for cable_info in link_with_resources['connections']:
            if cable_info['cable'] is not None:
                route_cabels.append(cable_info['cable']['name'])
        if reverse_cable_id_list:
            route_cabels.reverse()

        result_data = {'route_cables': route_cabels}

        if route_cabels:
            return result_data
        else:
            self.logger.error(f"reverse_cable_id_list: '{reverse_cable_id_list}'")
            self.logger.error(f"link_with_resources: '{link_with_resources}'")
            raise Exception(
                "Route information could not be retrieved. "
                f"Check reservation id '{reservation_id}' and connection."
                )

    def check_topology_conflicting_resources(self, topology_name, scheduled_time=0, duration=60, rawdata=True):
        """
        Method to check before reservation that is any device in topology
        conficting with other reservations. If only topology name given
        assumption is that reservation is immediately and duration 60min.
        If reservation is scheduled give scheduled_time as unix timestamp
        in milliseconds. Raise exeption if errors. If rawdata is False
        then return cleaned data where is information what device
        is conflicting and in what reservation.

        :param topology_name: The name of the topology to be reserved
        :type topology_name: str
        :param scheduled_time: Timestamp in milliseconds (13 digits)
        :type scheduled_time: int
        :param duration: How long resevation in minutes
        :type duration: int
        :param rawdata: Is data returned as it is or parsed
        :type rawdata: bool

        returns: conflicts
        rtype: dict[list]
        """

        starting_time = self.get_server_time()['time']
        if scheduled_time != 0:
            if (len(str(scheduled_time)) != 13):
                raise Exception("Given start_time lenght is wrong!")
            elif (starting_time > scheduled_time):
                raise Exception("Given start_time is in the past!")
            starting_time = scheduled_time
        ending_time = starting_time + (duration*60*1000)
        topology_info = self._get_topology_by_name(topology_name)
        if topology_info == {}:
            raise Exception(f'Given {topology_name} topology was not found!')
        topology_resources = self.get_topology_resources(topology_id=topology_info["id"])
        inventory_id_list = self._parse_inventory_ids(topology_resources)
        topology_devices = self._get_topology_devices_by_ids(inventory_id_list)["devices"]
        custom_reservation_times = self._parse_reservation_times(topology_resources, topology_devices)
        custom_utilizations = self._parse_utilizations(topology_resources)
        resolution = self._get_resolution(
                                            topology_info["versionId"],
                                            custom_reservation_times,
                                            custom_utilizations,
                                            starting_time,
                                            ending_time
                                         )
        conflicts = self._get_conglict_multiple(
                                                topology_info["versionId"],
                                                custom_reservation_times,
                                                custom_utilizations,
                                                resolution,
                                                starting_time,
                                                ending_time
                                               )
        if rawdata:
            return conflicts
        else:
            conflicts_list = []
            returned_info = {}
            for conflicts in conflicts["conflicts"]:
                if conflicts["conflictingResources"] != []:
                    for devices in conflicts["conflictingResources"]:
                        if devices["type"] == "DEVICE":
                            dev = {}
                            dev["name"] = devices['name']
                            inventory_id = devices['inventoryId']
                            for reservation in conflicts["resolutionSet"]["conflicts"]:
                                for id in reservation["resourceIds"]:
                                    if id["id"] == inventory_id:
                                        dev["res_name"] = reservation["reservation"]["name"]
                                        dev["res_id"] = reservation["reservation"]["id"]
                                        conflicts_list.append(dev)
                    returned_info["conflicts"] = conflicts_list
                    return returned_info
                else:
                    returned_info["conflicts"] = []
                    return returned_info

    def add_device_to_reservation(self, reservation_id, device_name, x_coordinate=100, y_coordinate=100,
                                  deferred=False):
        """
        Method for adding a device to a reservation.
        Works for active and scheduled reservations.
        Raise exception in case of an error!

        :param reservation_id: ID of the reservation
        :param device_name: Device inventory resource name
        :param x_coordinate: The X coordinate of added resource in the reserved topology
        :param y_coordinate: The Y coordinate of added resource in the reserved topology
        :param deferred: Information if the device should be deferred or reserved immediately
        """

        # check if reservation can be edited by current user
        self.check_reservation_access(reservation_id)
        try:
            lock_status = self.get_reservation_lock_status(reservation_id)
        except RestQueryException:
            raise Exception('Reservation cannot be edited now.')

        # get the devices id and check if device actually exists
        device = self.get_devices(filter=f'name::{device_name}')
        if device["total"] == 1:
            device_id = device["devices"][0]["id"]
        else:
            raise Exception(f'VC: Problems to find device {device_name}')

        # get resources of reservation
        rsv_resources = self.get_reservation_resources(reservation_id, limit=200)

        # check if the device is not already in the reservation
        try:
            self._is_device_in_resources(device_name, rsv_resources['items'])
        except Exception as e:
            if str(e) == f'Device not found! Check the name of {device_name}!':
                pass
            else:
                raise e
        else:
            raise Exception(f'Device {device_name} is already in the reservation')

        rsv_yaml = yaml.safe_load(
            self.get_reservation_yaml(reservation_id=reservation_id)
        )

        device_yaml = self._create_yaml_for_device(device_id, x_coordinate, y_coordinate, deferred)

        rsv_yaml['topology_template']['node_templates'].update(device_yaml)

        response, status = self._update_reservation_using_yaml(rsv_yaml, reservation_id)
        return {'job-id': response['jobId'], 'status': status}

    def change_connection(
                self, reservation_id, device_name, port_a,
                port_b):
        """
        Method for change connection between ports assuming a new connection
        is the same type as current. Change connection in active reservation.

        Connection type between devices in topology need to be coax, opt or sync
        Abstract devices: Deferred devices need to be activated before making
        change.
        Raise Exception in case of error!

        :param reservation_id: ID of the reservation
        :param device_name: Name of device on which connection will be change.
        :param port_a: Name of currently used port
        :param port_b: Name of new port
        :return: dict {job_id, status}
        """
        current_port_name = port_a
        new_port_name = port_b
        current_device_id = ""
        current_port_id = ""
        dev_inventory_name = ""

        rsv_yaml = yaml.safe_load(
            self.get_reservation_yaml(reservation_id=reservation_id)
        )
        res_resources = self.get_reservation_resources(reservation_id, limit=200)
        current_device_id, dev_inventory_name = self._get_inventory_id_and_name(res_resources,
                                                                                device_name,
                                                                                "DEVICE")
        current_port_id, port_inventory_name = self._get_inventory_id_and_name(res_resources=res_resources,
                                                                               name=port_a,
                                                                               type="PORT",
                                                                               id=current_device_id)

        new_port_inventory_id = self._get_device_port_id(current_device_id, new_port_name)
        if current_port_id == new_port_inventory_id:
            raise Exception("New port is same as current!")

        device_id_from_rsv = self._get_rsv_id(
            _type='Device',
            inventory_id=current_device_id,
            rsv_yaml=rsv_yaml
        )

        if not self._check_if_port_already_in_rsv(current_port_id, rsv_yaml):
            raise Exception("Current active port is different than given current port!")

        new_id = self._get_random_velocity_id(length=33, type="device")
        new_port_id = 'port_' + new_id
        for k, v in rsv_yaml['topology_template']['node_templates'].items():
            if v["type"] == "com.spirent.velocity.Port":
                if device_id_from_rsv == v["requirements"][0]["device"].replace('device_', ''):
                    if v["properties"]["name"] == current_port_name \
                        or v["properties"]["inventory_name"] == current_port_name:
                        rsv_yaml = self._change_port_id_in_link(rsv_yaml=rsv_yaml,
                                                                current_port_id_rsv=v["properties"]["id"],
                                                                new_port_id_for_rsv=new_id)
                        v["properties"]["id"] = new_id
                        v["properties"]["inventory_id"] = new_port_inventory_id
                        v["properties"]["inventory_name"] = new_port_name
                        v["properties"]["name"] = new_port_name
                        for item in v["properties"]["property_groups"]:
                            for group in item["group"]:
                                group["id"] = self._get_random_velocity_id(length=33, type="device")
                                if group["value"] == current_port_name:
                                    group["value"] = new_port_name
                                    break
                        rsv_yaml['topology_template']['node_templates'][new_port_id] = rsv_yaml['topology_template']['node_templates'][k]
                        del rsv_yaml['topology_template']['node_templates'][k]
                        break

        response, status = self._update_reservation_using_yaml(rsv_yaml, reservation_id)
        return {'job-id': response['jobId'], 'status': status}

    def change_abstract_resource_condition(self,
                                           reservation_id,
                                           abstract_resource_name,
                                           abstract_resource_condition=None,
                                           abstract_ports_condition=None,
                                           wait_time=200):
        """
        Method to change abstract resource condition during active resercvation. Abstract
        ports conditions can be changed using dictionary. Resources should be in INACTIVE
        state.

        Example of abstract port change:
        {"Port_1": "New condition"}

        :param reservation_id: ID of the reservation
        :res_type reservation_id: str
        :param abstract_resource_name: Name of abstract resource whose condition will be changed. Can be type 'None' if no resource change.
        :res_type abstract_resource_name: str
        :param abstract_resource_condition: New condition statement.
        :res_type abstract_resource_condition: str
        :param abstract_ports_condition: Dictionary of ports and condition pairs. Can be type 'None' if no port change.
        :abstract_ports_condition: dict

        :return: dict {job_id, status}
        """
        self.check_reservation_access(reservation_id)
        rsv_yaml = yaml.safe_load(
            self.get_reservation_yaml(reservation_id=reservation_id)
        )
        resource_id = self._get_resource_id(rsv_yaml, abstract_resource_name)

        if self._check_is_abs_ready_for_update(
                        reservation_id,
                        abstract_resource_name,
                        wait_time=wait_time):
            if abstract_resource_condition:
                self._change_yaml_condition(rsv_yaml, resource_id, abstract_resource_condition)
            if abstract_ports_condition:
                self._change_abstract_ports_cond_in_yaml(abstract_ports_condition,
                                                        rsv_yaml,
                                                        res_id=resource_id)
        response, status = self._update_reservation_using_yaml(rsv_yaml, reservation_id)
        return {'job-id': response['jobId'], 'status': status}

    def get_queue_reason(self, reservation_id, device=None, raw=False):
        """
        Get information why resource or reservation is in queue.
        If only reservation id is defined will return all budles for the id.
        If also device is defined will return only bundles where demandedResourcesNames
        include device name.
        If raw is True will return full bundle information. Default is False and will return
        minimal information.

        :pram reservation_id: Id of reservation
        :res_type reservation_id: str
        :pram device: Single device name queued
        :res_type device: str
        :pram raw: Raw bundle data or parsed data
        :res_type raw: bool
        :pram items: Limit how many items is returned
        :res_type items: int
        :return: dict {bundles:[list]}
        """
        bundles = self.get_bundles(limit=200)
        result = {"bundles": []}
        for bundle in bundles["items"]:
            if bundle["id"] == reservation_id:
                if device:
                    if device in bundle["demandedResourcesNames"]:
                        result["bundles"].append(bundle if raw is True else self._parse_bundle(bundle))
                        return result
                else:
                    result["bundles"].append(bundle if raw is True else self._parse_bundle(bundle))
        return result

    def activate_deferred_group(self, reservation_id, group_name):
        """
        Can be used to activate deferred devices from device group or subtopology
        in active reservation. Will activate all devices in group.

        :pram reservation_id: Id of reservation
        :res_type reservation_id: str
        :pram group_name: Name of the group or subtopology
        :res_type device: str
        :return: dict
        """
        if None in (reservation_id, group_name):
            return {"status": "FAILED", "result": "Missing parameter."}
        device_ids = self._get_group_device_ids(reservation_id, group_name)
        activation_ids = self._get_group_activation_id_list(reservation_id, device_ids)
        if activation_ids == []:
            return {"status": "FAILED", "result": "Check reservation id and group name."}
        result = self.activate_deferred_resource_from_reservation(reservation_id, activation_ids)
        return result

    def release_deferred_group(self, reservation_id, group_name):
        """
        Can be used to release deferred devices from device group or subtopology
        in active reservation. Will release all devices in group.

        :pram reservation_id: Id of reservation
        :res_type reservation_id: str
        :pram group_name: Name of the group or subtopology
        :res_type device: str
        :return: dict
        """
        if None in (reservation_id, group_name):
            return {"status": "FAILED", "result": "Missing parameter."}
        device_ids = self._get_group_device_ids(reservation_id, group_name)
        activation_ids = self._get_group_activation_id_list(reservation_id, device_ids)
        if activation_ids == []:
            return {"status": "FAILED", "result": "Check reservation id and group name."}
        result = self.release_deferred_resource_from_reservation(reservation_id, activation_ids)
        return result

    def create_connection_between_devices(
            self, reservation_id, first_device_name, first_port_name,
            sec_device_name, sec_port_name, cabel_type="Coax", bidirectional=True
    ):
        """
        Method to create connection link between two devices.

        Accepted cabel_type values: Coax, Opt, Gen, RP3, Eth
        Raise Exception in case of error!

        :param reservation_id: ID of the reservation
        :param first_device_name: Name of the first device
        :param first_port_name: Name of the port in first device
        :param sec_device_name: Name of the second device
        :param sec_port_name: Name of the port in second device
        :param cabel_type: Tyle of the link.
        :param bidirectional: Is connection bidirectional
        :return: dict {job_id, status}
        """
        link_types = ['coax', 'opt', 'rp3', 'sync', 'eth', 'gen']

        if cabel_type.lower() not in link_types:
            raise Exception(f'Incorrect cabel_type {cabel_type}.')

        rsv_yaml = yaml.safe_load(
            self.get_reservation_yaml(reservation_id=reservation_id)
        )

        res_devices = self.get_reservation_resources(reservation_id, limit=200)["items"]
        self._is_device_in_resources(first_device_name, res_devices)
        self._is_device_in_resources(sec_device_name, res_devices)

        new_first_port_id_for_rsv = self._get_random_velocity_id(length=33, type="port")
        new_sec_port_id_for_rsv = self._get_random_velocity_id(length=33, type="port")

        first_link_yaml = self._create_port_link_info_for_yaml(first_device_name,
                                                               first_port_name,
                                                               new_first_port_id_for_rsv,
                                                               res_devices,
                                                               rsv_yaml)

        sec_link_yaml = self._create_port_link_info_for_yaml(sec_device_name,
                                                             sec_port_name,
                                                             new_sec_port_id_for_rsv,
                                                             res_devices,
                                                             rsv_yaml)

        rsv_yaml['topology_template']['node_templates'].update(first_link_yaml)
        rsv_yaml['topology_template']['node_templates'].update(sec_link_yaml)

        link_setup = self._create_yaml_link_info_for_new_connection(cabel_type,
                                                                    bidirectional,
                                                                    new_first_port_id_for_rsv,
                                                                    new_sec_port_id_for_rsv
                                                                    )

        rsv_yaml['topology_template']['node_templates'].update(link_setup)

        try:
            self.create_reservation_lock(reservation_id=reservation_id)
            response = self.update_reservation_tbml_by_yaml(
                reservation_id=reservation_id,
                body=rsv_yaml
            )
            self.delete_reservation_lock(reservation_id=reservation_id)
        except Exception as e:
            self.delete_reservation_lock(reservation_id=reservation_id)
            raise Exception(f'Reservation updata failed: {e}')
        status = self._check_status_of_modification(
            response['jobId'], reservation_id
        )
        return {'job-id': response['jobId'], 'status': status}

    def create_vlan_connection(self, reservation_id, device_name, port_name, vlan_id,
                               cabel_type='vlan', bidirectional=True):
        """
        Can be used in reservation to create vlan connection between device and
        active vlan. vlan have to be active and have the id.

        Raise Exception in case of error!

        :pram reservation_id: Id of reservation
        :res_type reservation_id: str
        :pram device_name: Device name
        :res_type device_name: str
        :pram port_name: Device port name where to connect
        :res_type port_name: str
        :pram vlan_id: vlan id number in reservation
        :res_type vlan_id: str
        :return: dict{job_id, status}
        """
        rsv_yaml = yaml.safe_load(
            self.get_reservation_yaml(reservation_id=reservation_id)
        )

        res_devices = self.get_reservation_resources(reservation_id, limit=200)["items"]
        self._is_device_in_resources(device_name, res_devices)
        vlans = self.get_reservation_vlans(reservation_id)
        self._is_vlan_in_reservation(vlan_id, vlans)
        for vlan in vlans:
            if vlan["vlanIds"] == vlan_id:
                vlan_original_id = vlan["originalId"]

        new_port_id_for_rsv = self._get_random_velocity_id(length=33, type="port")
        port_link_to_yaml = self._create_port_link_info_for_yaml(
                                                        device_name,
                                                        port_name,
                                                        new_port_id_for_rsv,
                                                        res_devices, rsv_yaml)

        rsv_yaml['topology_template']['node_templates'].update(port_link_to_yaml)

        link_setup = self._create_yaml_link_info_for_new_connection(
                                                            cabel_type,
                                                            bidirectional,
                                                            new_port_id_for_rsv,
                                                            vlan_original_id
                                                            )

        rsv_yaml['topology_template']['node_templates'].update(link_setup)
        response, status = self._update_reservation_using_yaml(rsv_yaml, reservation_id)
        return {'job-id': response['jobId'], 'status': status}

    def get_users_user_groups(self, user_login_name=""):
        """
        Get user's user groups. If login name given will return information for that user.
        Otherwise, will get information for current used credentials.

        :param user_login_name: User's login name to Velocity. (Optional)
        :res_type user_login_name: str
        :return: dict {name:str, login:str, role:str, groups:dict}
        """
        usergroups = {}
        user = {}
        if user_login_name != "":
            users = self.get_profiles(filter=f'login::{user_login_name}')
            if users["total"] != 1:
                return {"status": "FAILED", "result": "Too many or none user found. Please check username."}
            user = users["profiles"][0]
        else:
            user = self.get_current_user()
        usergroups = self._parse_user_groups(user)
        return {"name": user["name"], "login": user["login"], "role": user["role"], "groups": usergroups}

    def get_user_group_id(self, user_group_name):
        """
        Get user group's UUID by its name. If userGroup of given name exists, will return UUID of that group.
        If it doesn't, an exception will be raised

        :param user_group_name: Name of the userGroup
        :res_type user_group_name: str
        :return: uuid: str
        """
        this_limit = 200
        this_offset = 0
        this_count = this_limit

        while this_count == this_limit:
            groups = self.get_groups(limit=this_limit, offset=this_offset)
            for group in groups["userGroups"]:
                if group["name"] == user_group_name:
                    return group["id"]
            this_count = groups["count"]
            this_offset += 200

        raise Exception(f"User group has not been found. Please check user group name: {user_group_name}")

    def get_reservation_resource_groups(self, reservation_id):
        """
        Get groups and subtopologies in reservation topology. Will return list of names in
        dictionary. Name can be use to activate all deferred devices in group or subtopology using
        activate_deferred_group support service. Use release_deferred_group to release.

        :pram reservation_id: Reservation id
        :res_type reservation_id: str
        :return: dict {group_names:list}
        """
        rsv_yaml = yaml.safe_load(
            self.get_reservation_yaml(reservation_id=reservation_id)
        )
        groups = {"group_names": []}
        for item in rsv_yaml["topology_template"]["groups"].values():
            groups["group_names"].append(item['properties']["name"])
        return groups

    def check_reservation_access(self, reservation_id):
        """
        Check does current user have access to reservation. Raise RestQueryException if
        no access. If current user is owner or reservation is shared with current user
        no actions.

        :pram reservation_id: Reservation id
        :res_type reservation_id: str

        If no access: raise RestQueryException
        """
        reservation = self.get_reservation(reservation_id)
        current_user = self.get_current_user()
        current_user_id = current_user["id"]
        groups = []
        for id in current_user["groups"]:
            groups.append(id["id"])
        if not any(item["id"] == current_user_id for item in reservation["sharedUsers"]) \
                    and current_user_id != reservation["creatorId"] \
           and not any(item["id"] in groups for item in reservation["sharedUserGroups"]):
            self.logger.info(f'User {current_user_id} group ids: {groups}')
            self.logger.info(f'Reservation shared users: {reservation["sharedUsers"]}')
            self.logger.info(f'Reservation shared groups: {reservation["sharedUserGroups"]}')
            raise RestQueryException('ACCESS_DENIED: You do not have permissions to update the reservation!')

    def get_reservation_time_left(self, reservation_id):
        """
        Return topology reservation left time as sec

        :pram reservation_id: Reservation id
        :res_type reservation_id: str
        :return: int (duration_left_sec)
        """
        current_time_sec = self.get_server_time()['time'] / 1000
        end_time_sec = self.get_reservation(reservation_id)["end"] / 1000
        duration_left_sec = int(end_time_sec - current_time_sec)
        return duration_left_sec

    def power_on(self,
                 reservation_id,
                 device_list=None,
                 status_check=False,
                 wait_time=300):
        """
        Method for power on devices from device list
        Args:
            reservation_id: str ID of reservation
            device_list: list of devices for power on. Default ALL
            status_check: bool Check status of powering is completed.
                          Raise exception if not completed
            wait_time: int Time to wait for powering execution completion

        Returns:
            response: dict Details of execution

        """""
        if device_list is None:
            device_list = ["ALL"]
        body = {
            "testPath": "main/nokia_pwr_ctrl/power_on.fftc",
            "reservationID": reservation_id,
            "parametersList": [
                {
                    "name": "DEVICE_LIST",
                    "value": ','.join(device_list)
                }
            ]
        }
        execution = self.add_execution(body=body)
        if status_check:
            status = self.wait_powering(execution_id=execution["executionID"],
                                        wait_time=wait_time)
            self.logger.info(f"Power on execution: {status}")
        return execution

