    def wait_powering(self, execution_id, wait_time=300):
        started_waiting = time.time()
        bad_state = ["START_FAILED", "ABORTED", "AGENT_NOT_RESPONDING"]
        bad_result = ["ABORT", "CANCEL", "ERROR", "FAIL"]
        while time.time() < started_waiting + wait_time:
            time.sleep(5)
            execution = self.get_execution(execution_id)
            print(f'State: {execution["executionState"]} Result: {execution["result"]}')
            if execution["executionState"] == "COMPLETED" and execution["result"] == "PASS":
                return "COMPLETED"
            elif execution["executionState"] in bad_state or execution["result"] in bad_result:
                raise Exception(f'Powering failed. State: {execution["executionState"]} '
                                + f'Result: {execution["result"]}')
        raise Exception(f'Timeout. Powering state: {execution["executionState"]}, '
                        + f'result: {execution["result"]}')

    def reserve_device(self, **kwargs):
        """
        Use to reserve resource without topology.
        Give eather device inventory name or inventory id
        to reserve.

        If want to reserve just a port give device id or name and port
        inventory name.

        If using username to get email, check that email address is
        defined to Velocity user settings!

        Return reservation id, reservation name and device name in dict

        :param device_name: Inventory resource name
        :param device_id: Inventory id of resource
        :param port_name: Device port inventory name
        :param email: Email address to send report
        :param username: login name to get user email
        :param res_name: Name of the reservation
        :param description: Description for reservation
        :param res_time: Reservation time in minutes
        :return: dict {id, name, device_name}
        """
        device_name = kwargs.get("device_name", "")
        device_id = kwargs.get("device_id", "")
        port_name = kwargs.get("port_name", "")
        email = kwargs.get("email", "")
        username = kwargs.get("username", "")
        res_name = kwargs.get("res_name", "OUT OF SERVICE")
        description = kwargs.get("description", "Please check the resource!")
        res_time = kwargs.get("res_time", 300000)
        timestamp = self._calculate_timestamp(res_time)
        port_id = ""

        if device_name != "":
            device = self.get_devices(filter=f'name::{device_name}')
            if device["total"] == 1:
                device_id = device["devices"][0]["id"]
            else:
                raise Exception(f'VC: Problems to find device {device_name}')
        elif device_id != "":
            try:
                device_name = self.get_device(device_id)["name"]
            except Exception as e:
                raise Exception(f'VC: Device could not be found: {e}')
        else:
            raise Exception("VC: Device name or id is required!")
        if username != "":
            email = self._get_user_by_username(username)["email"]
            if email is None:
                self.logger.warning(
                    'VC: The user has not defined email address to Velocity profile')
                email = ""

        if port_name != "":
            port_id = self._get_device_port_id(device_id, port_name)
            if port_id == "":
                raise Exception(f'VC: Problems to find port {port_name} for device {device_name}')
            body = {
                "name": res_name,
                "end": timestamp,
                "isQueued": True,
                "description": description,
                "resources": [
                    {
                        "inventoryParentResourceId": device_id,
                        "inventoryResourceId": port_id,
                        "utilizationType": "EXCLUSIVE"
                    }],
                "customResourceConfigurations": [{
                    "resourceId": port_id
                }]
            }
        else:
            body = {
                "name": res_name,
                "end": timestamp,
                "isQueued": True,
                "description": description,
                "resources": [
                    {
                        "inventoryResourceId": device_id,
                        "utilizationType": "EXCLUSIVE"
                    }
                ]}
        try:
            reservation = self.create_reservation(body)
        except Exception as e:
            raise Exception(f'VC: Problems to create reservation: {e}')

        if email != "":
            try:
                message = self._device_reservation_report_message(device_name,
                                                                  res_name,
                                                                  reservation["id"])
                email_subject = f'[VELOCITY RESERVATION] {res_name}'
                self.send_email_report(from_mail=None,
                                       to_mails=email,
                                       subject=email_subject,
                                       content=message)
            except Exception as e:
                self.logger.warning(
                    f'VC: Problems to send report: {e}')

        return {"id": reservation["id"], "name": res_name, "device_name": device_name}

    def get_resources_of_abstract_condition(self, condition, raw=False):
        """
        Get resources of abstract condition. If raw is True will return all information
        from Velocity. If raw is False will return dictionary where key is resource id and
        value is resource lock status.
        :param condition: Condition of abstract resource
        :param raw: Return raw data or parsed data
        :return: dict
        """
        encoded_condition = urllib.parse.quote(condition)
        resources = self.get_device_search(limit=200, searchString=encoded_condition)
        print(f'Total resources found: {resources["total"]}')
        if raw:
            return resources
        devices = {}
        for device in resources["devices"]:
            devices[device["id"]] = device["isLocked"]
        return devices

    def get_resource_reservations(self, device_list):
        """
        Will get reservations for the devices and ports.

        :param device_list: Give the list of devices from get_resources_of_abstract_condition method using raw=True

        Return dictionary where key is device id
        "7546608c-855a-40cd-8ef4-77efeb2cefc5": {
                                        "isReserved": True,
                                        "reservationId": [],
                                        "status": "ACTIVE"
                                                }
        """
        resources_dict = {}
        for device in device_list:
            if device["isLocked"]:
                reservations = self.get_reservations(limit=200, filter=f'resourceId::{device["id"]}&status::ACTIVE')
                for reservation in reservations["items"]:
                    resources = self.get_reservation_resources(reservation_id=reservation["id"], limit=200)
                    for res_dev in resources["items"]:
                        if device["id"] == res_dev["inventoryResourceId"] and res_dev["status"] == "ACTIVE":
                            if device["id"] in resources_dict:
                                resources_dict[device["id"]]["reservationIds"].append(reservation["id"])
                                continue
                            resources_dict[device["id"]] = {"isReserved": device["isLocked"], "reservationIds": [reservation["id"]], "status": res_dev["status"]}
                            continue
            else:
                resources_dict[device["id"]] = {"isReserved": device["isLocked"], "reservationIds": [], "status": ""}

            # Check if any device port has reservations
            for dev_id, dev_data in resources_dict.items():
                dev_ports = self.get_device_ports(dev_id,
                                                  limit=200,
                                                  filter="connectedPortParentId:!:null")
                for port in dev_ports["ports"]:
                    if port["isLocked"]:
                        port_reservations = self.get_reservations(limit=200,
                                                                  filter=f'resourceId::{port["id"]}&status::ACTIVE')
                        for port_res in port_reservations["items"]:
                            if port_res["id"] not in dev_data["reservationIds"]:
                                dev_data["reservationIds"].append(port_res["id"])
        return resources_dict
